    },

    disconnect(): void {
      stopHeartbeat();
      connected = false;

      for (const request of pending.values()) {
        window.clearTimeout(request.timeoutId);
        request.reject(new Error('SharedHubClient disconnected'));
      }
      pending.clear();

      port?.close();
      port = null;
      worker = null;
