    subscribe(topic: Topic, handler: EventHandler): () => void {
      let handlers = topicHandlers.get(topic);
      if (!handlers) {
        handlers = new Set();
        topicHandlers.set(topic, handlers);
        if (connected) post('subscribe', { topic });
      }

      handlers.add(handler);

